					return cb(err);
				}
				cb();
			});

		} else {
			self.pool.getConnection(function(err, connection) {
				if (err) {
					log("warning", "error in deleteOldDbOps (get Conection)" + err.toString());
					return cb(err);
				}
				addConnectionLog(connection, log);
				connection.log("verbose","DELETE old dbops", {sql: sql});
				connection.query(sql, [lastId], function(err) {
					if(err) {
						connection.log("warning", "Error Deleting Old DBOps: " + err, { sql: sql});
